export const CONTEXT_XRAY_MANIFEST_KEY = "context_xray:manifest";
export function manifestSystemTokens(manifest) {
    return (manifest.systemTokens ??
        manifest.systemSections?.reduce((total, section) => total + section.tokenCount, 0) ??
        0);
}
export function manifestConversationTokens(manifest) {
    return (manifest.conversationTokens ??
        Math.max(0, manifest.totalTokens - manifestSystemTokens(manifest)));
}
export function emptyContextManifest(threadId, opts = {}) {
    return {
        threadId,
        ...(opts.turnId ? { turnId: opts.turnId } : {}),
        computedAt: Date.now(),
        ...(opts.model ? { model: opts.model } : {}),
        totalTokens: 0,
        rawTokens: 0,
        reclaimedTokens: 0,
        tokenCountMethod: "estimate",
        source: opts.source ?? "structured",
        enforceable: opts.enforceable ?? true,
        segments: [],
        conversationTokens: 0,
        systemTokens: 0,
        systemSections: [],
    };
}
